<script>
// ============================================
// PROCEDURAL TEXTURE GENERATION
// ============================================
function createCoinTexture(metal, face, size=512) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Base metal color
  const colors = {
    bronze: { base:'#cd7f32', light:'#e8a85e', dark:'#8b5a2b', spec:'#ffd700' },
    silver: { base:'#b8bcc0', light:'#e8ebef', dark:'#8a8e92', spec:'#ffffff' },
    gold:   { base:'#d4af37', light:'#f0e68c', dark:'#9e7d2a', spec:'#fff8dc' },
    black:  { base:'#1a1a2e', light:'#2d2d44', dark:'#0a0a1a', spec:'#4a4a6a' }
  };
  const c = colors[metal] || colors.bronze;

  // Radial gradient base
  const grad = ctx.createRadialGradient(size/2, size/2, 0, size/2, size/2, size/2);
  grad.addColorStop(0, c.light);
  grad.addColorStop(0.5, c.base);
  grad.addColorStop(1, c.dark);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  // Brushed metal texture
  for(let i=0;i<size*1.5;i++){
    ctx.strokeStyle = `rgba(255,255,255,${Math.random()*0.02})`;
    ctx.beginPath();
    ctx.moveTo(Math.random()*size, 0);
    ctx.lineTo(Math.random()*size, size);
    ctx.stroke();
  }
  for(let i=0;i<size*1.5;i++){
    ctx.strokeStyle = `rgba(0,0,0,${Math.random()*0.02})`;
    ctx.beginPath();
    ctx.moveTo(0, Math.random()*size);
    ctx.lineTo(size, Math.random()*size);
    ctx.stroke();
  }

  if(face === 'front') {
    // WastedToken Mint Emblem - Raised Relief Style
    ctx.save();
    ctx.translate(size/2, size/2);

    // Outer ring text
    ctx.font = `bold ${size*0.07}px 'Segoe UI', system-ui`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const ringText = 'WASTEDTOKEN MINT  •  EST. 2021  •';
    const radius = size*0.38;

    // Embossed ring - dark shadow
    ctx.fillStyle = c.dark;
    for(let a=-Math.PI/2; a<3*Math.PI/2; a+=0.05){
      const ch = ringText[Math.floor((a+Math.PI/2)/(2*Math.PI)*ringText.length)%ringText.length];
      const x = Math.cos(a)*radius;
      const y = Math.sin(a)*radius;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(a+Math.PI/2);
      ctx.fillText(ch, 1, 1);
      ctx.restore();
    }
    // Embossed ring - light highlight
    ctx.fillStyle = c.light;
    for(let a=-Math.PI/2; a<3*Math.PI/2; a+=0.05){
      const ch = ringText[Math.floor((a+Math.PI/2)/(2*Math.PI)*ringText.length)%ringText.length];
      const x = Math.cos(a)*radius;
      const y = Math.sin(a)*radius;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(a+Math.PI/2);
      ctx.fillText(ch, -1, -1);
      ctx.restore();
    }
    // Main ring text
    ctx.fillStyle = c.base;
    for(let a=-Math.PI/2; a<3*Math.PI/2; a+=0.05){
      const ch = ringText[Math.floor((a+Math.PI/2)/(2*Math.PI)*ringText.length)%ringText.length];
      const x = Math.cos(a)*radius;
      const y = Math.sin(a)*radius;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(a+Math.PI/2);
      ctx.fillText(ch, 0, 0);
      ctx.restore();
    }

    // Central emblem - stylized waste/token symbol
    // Outer circle
    const emblemR = size*0.22;
    // Embossed circle
    ctx.strokeStyle = c.dark; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(1,1,emblemR,0,Math.PI*2); ctx.stroke();
    ctx.strokeStyle = c.light;
    ctx.beginPath(); ctx.arc(-1,-1,emblemR,0,Math.PI*2); ctx.stroke();
    ctx.strokeStyle = c.base; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0,0,emblemR,0,Math.PI*2); ctx.stroke();

    // Inner triangle (recycle/waste symbol)
    const triR = emblemR*0.65;
    ctx.fillStyle = c.dark;
    ctx.beginPath();
    for(let i=0;i<3;i++){
      const a = -Math.PI/2 + i*2*Math.PI/3;
      ctx.lineTo(Math.cos(a)*triR+1, Math.sin(a)*triR+1);
    }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = c.light;
    ctx.beginPath();
    for(let i=0;i<3;i++){
      const a = -Math.PI/2 + i*2*Math.PI/3;
      ctx.lineTo(Math.cos(a)*triR-1, Math.sin(a)*triR-1);
    }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = c.base;
    ctx.beginPath();
    for(let i=0;i<3;i++){
      const a = -Math.PI/2 + i*2*Math.PI/3;
      ctx.lineTo(Math.cos(a)*triR, Math.sin(a)*triR);
    }
    ctx.closePath(); ctx.fill();

    // Center hole of triangle
    ctx.fillStyle = c.dark;
    ctx.beginPath(); ctx.arc(1,1,triR*0.35,0,Math.PI*2); ctx.fill();
    ctx.fillStyle = c.light;
    ctx.beginPath(); ctx.arc(-1,-1,triR*0.35,0,Math.PI*2); ctx.fill();
    ctx.fillStyle = c.base;
    ctx.beginPath(); ctx.arc(0,0,triR*0.35,0,Math.PI*2); ctx.fill();

    // Small text at bottom
    ctx.font = `500 ${size*0.035}px system-ui`;
    ctx.fillStyle = c.dark;
    ctx.fillText('PHYSICAL • FINITE • FINAL', 1, emblemR+size*0.05+1);
    ctx.fillStyle = c.light;
    ctx.fillText('PHYSICAL • FINITE • FINAL', -1, emblemR+size*0.05-1);
    ctx.fillStyle = c.base;
    ctx.fillText('PHYSICAL • FINITE • FINAL', 0, emblemR+size*0.05);

    ctx.restore();
  } else {
    // Back face - Denomination
    ctx.save();
    ctx.translate(size/2, size/2);

    // Large token count
    ctx.font = `bold ${size*0.18}px 'Segoe UI', system-ui`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Embossed effect
    ctx.fillStyle = c.dark;
    ctx.fillText('10,000', 2, 2);
    ctx.fillStyle = c.light;
    ctx.fillText('10,000', -2, -2);
    ctx.fillStyle = c.base;
    ctx.fillText('10,000', 0, 0);

    // TOKENS text
    ctx.font = `600 ${size*0.07}px system-ui`;
    ctx.letterSpacing = '0.2em';
    ctx.fillStyle = c.dark;
    ctx.fillText('TOKENS', 1, size*0.14+1);
    ctx.fillStyle = c.light;
    ctx.fillText('TOKENS', -1, size*0.14-1);
    ctx.fillStyle = c.base;
    ctx.fillText('TOKENS', 0, size*0.14);

    // Serial number area (decorative)
    ctx.font = `${size*0.035}px monospace`;
    ctx.fillStyle = c.dark;
    ctx.fillText('S/N: WT-XXXX-XXXX', 1, -size*0.28+1);
    ctx.fillStyle = c.light;
    ctx.fillText('S/N: WT-XXXX-XXXX', -1, -size*0.28-1);
    ctx.fillStyle = c.base;
    ctx.fillText('S/N: WT-XXXX-XXXX', 0, -size*0.28);

    // Bottom mark
    ctx.font = `500 ${size*0.03}px system-ui`;
    ctx.fillStyle = c.dark;
    ctx.fillText('WASTEDTOKEN.MINT', 1, size*0.32+1);
    ctx.fillStyle = c.light;
    ctx.fillText('WASTEDTOKEN.MINT', -1, size*0.32-1);
    ctx.fillStyle = c.base;
    ctx.fillText('WASTEDTOKEN.MINT', 0, size*0.32);

    ctx.restore();
  }

  return canvas;
}

// ============================================
// WEBGL RENDERER - HERO COIN
// ============================================
class CoinRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.gl = canvas.getContext('webgl2', {antialias:true, alpha:false, preserveDrawingBuffer:true});
    if(!this.gl) throw new Error('WebGL2 not supported');

    this.time = 0;
    this.paused = false;
    this.animId = null;

    this.initShaders();
    this.initGeometry();
    this.initTextures();
    this.resize();
    window.addEventListener('resize', () => this.resize());

    this.start();
  }

  initShaders() {
    const gl = this.gl;

    // Vertex shader - supports both faces and edge
    const vsSrc = `#version 300 es
    precision highp float;
    in vec3 aPos; in vec3 aNormal; in vec2 aUV; in float aFace;
    uniform mat4 uModel; uniform mat4 uView; uniform mat4 uProj;
    uniform vec3 uLightDir; uniform vec3 uViewPos;
    out vec3 vWorldPos; out vec3 vNormal; out vec2 vUV; out float vFace;
    out vec3 vViewDir; out vec3 vLightDir;
    void main(){
      vec4 worldPos = uModel * vec4(aPos, 1.0);
      vWorldPos = worldPos.xyz;
      vNormal = mat3(uModel) * aNormal;
      vUV = aUV; vFace = aFace;
      vViewDir = normalize(uViewPos - vWorldPos);
      vLightDir = normalize(uLightDir);
      gl_Position = uProj * uView * worldPos;
    }`;

    // Fragment shader - Cook-Torrance BRDF for metallic
    const fsSrc = `#version 300 es
    precision highp float;
    in vec3 vWorldPos; in vec3 vNormal; in vec2 vUV; in float vFace;
    in vec3 vViewDir; in vec3 vLightDir;
    uniform sampler2D uFrontTex; uniform sampler2D uBackTex;
    uniform vec3 uBaseColor; uniform float uRoughness; uniform float uMetalness;
    uniform vec3 uLightColor; uniform float uTime;
    out vec4 fragColor;

    const float PI = 3.14159265359;

    float DistributionGGX(vec3 N, vec3 H, float roughness){
      float a = roughness*roughness; float a2 = a*a;
      float NdotH = max(dot(N,H), 0.0); float NdotH2 = NdotH*NdotH;
      float num = a2; float denom = (NdotH2*(a2-1.0)+1.0);
      denom = PI*denom*denom; return num/denom;
    }
    float GeometrySchlickGGX(float NdotV, float roughness){
      float r = roughness+1.0; float k = (r*r)/8.0;
      return NdotV/(NdotV*(1.0-k)+k);
    }
    float GeometrySmith(vec3 N, vec3 V, vec3 L, float roughness){
      float NdotV = max(dot(N,V),0.0); float NdotL = max(dot(N,L),0.0);
      float ggx2 = GeometrySchlickGGX(NdotV,roughness);
      float ggx1 = GeometrySchlickGGX(NdotL,roughness);
      return ggx1*ggx2;
    }
    vec3 fresnelSchlick(float cosTheta, vec3 F0){
      return F0 + (1.0-F0)*pow(clamp(1.0-cosTheta,0.0,1.0),5.0);
    }

    // Procedural environment for reflections
    vec3 envMap(vec3 R){
      // Simple procedural skybox
      float horizon = smoothstep(-0.1, 0.3, R.y);
      vec3 skyColor = mix(vec3(0.02,0.02,0.04), vec3(0.15,0.12,0.08), horizon);
      vec3 groundColor = vec3(0.01);
      vec3 sunDir = normalize(vec3(sin(uTime*0.5), 0.5, cos(uTime*0.5)));
      float sun = pow(max(dot(R, sunDir), 0.0), 256.0);
      vec3 sunColor = vec3(1.0, 0.9, 0.7) * sun * 3.0;
      // Rim highlight
      float rim = pow(max(dot(R, vec3(0,1,0)), 0.0), 8.0) * 0.3;
      return skyColor + sunColor + vec3(rim);
    }

    void main(){
      vec3 N = normalize(vNormal);
      vec3 V = normalize(vViewDir);
      vec3 L = vLightDir;

      // Select texture
      vec3 albedo = texture(vFace > 0.5 ? uFrontTex : uBackTex, vUV).rgb;

      // Metallic workflow
      vec3 F0 = mix(vec3(0.04), albedo, uMetalness);
      float NdotV = max(dot(N,V), 0.0);
      float NdotL = max(dot(N,L), 0.0);
      if(NdotL <= 0.0){
        // Backface or unlit - subtle ambient
        fragColor = vec4(albedo * 0.05 + envMap(reflect(-V,N)) * uMetalness * 0.1, 1.0);
        return;
      }

      vec3 H = normalize(V + L);
      float NdotH = max(dot(N,H), 0.0);
      float VdotH = max(dot(V,H), 0.0);

      float D = DistributionGGX(N, H, uRoughness);
      float G = GeometrySmith(N, V, L, uRoughness);
      vec3 F = fresnelSchlick(VdotH, F0);

      vec3 nominator = D * G * F;
      float denominator = 4.0 * NdotV * NdotL + 0.001;
      vec3 specular = nominator / denominator;

      vec3 kS = F; vec3 kD = (1.0 - kS) * (1.0 - uMetalness);
      vec3 radiance = uLightColor * NdotL;
      vec3 direct = (kD * albedo / PI + specular) * radiance;

      // Environment reflection
      vec3 R = reflect(-V, N);
      vec3 env = envMap(R);
      vec3 indirect = (kD * albedo / PI + specular * F) * env * 0.5;

      // Edge highlight for reeded edge
      float edgeFactor = 1.0 - abs(N.y);
      vec3 edgeGlow = vec3(0.0);
      if(vFace == 0.5){
        edgeGlow = uLightColor * pow(edgeFactor, 4.0) * 2.0;
      }

      vec3 color = direct + indirect + edgeGlow;
      color = color / (color + vec3(1.0)); // tone map
      color = pow(color, vec3(1.0/2.2)); // gamma

      fragColor = vec4(color, 1.0);
    }`;

    const compile = (src, type) => {
      const s = gl.createShader(type);
      gl.shaderSource(s, src); gl.compileShader(s);
      if(!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s));
      return s;
    };

    const vs = compile(vsSrc, gl.VERTEX_SHADER);
    const fs = compile(fsSrc, gl.FRAGMENT_SHADER);

    this.program = gl.createProgram();
    gl.attachShader(this.program, vs); gl.attachShader(this.program, fs);
    gl.linkProgram(this.program);
    if(!gl.getProgramParameter(this.program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(this.program));

    gl.useProgram(this.program);

    // Attributes
    this.aPos = gl.getAttribLocation(this.program, 'aPos');
    this.aNormal = gl.getAttribLocation(this.program, 'aNormal');
    this.aUV = gl.getAttribLocation(this.program, 'aUV');
    this.aFace = gl.getAttribLocation(this.program, 'aFace');

    // Uniforms
    this.uModel = gl.getUniformLocation(this.program, 'uModel');
    this.uView = gl.getUniformLocation(this.program, 'uView');
    this.uProj = gl.getUniformLocation(this.program, 'uProj');
    this.uLightDir = gl.getUniformLocation(this.program, 'uLightDir');
    this.uViewPos = gl.getUniformLocation(this.program, 'uViewPos');
    this.uFrontTex = gl.getUniformLocation(this.program, 'uFrontTex');
    this.uBackTex = gl.getUniformLocation(this.program, 'uBackTex');
    this.uBaseColor = gl.getUniformLocation(this.program, 'uBaseColor');
    this.uRoughness = gl.getUniformLocation(this.program, 'uRoughness');
    this.uMetalness = gl.getUniformLocation(this.program, 'uMetalness');
    this.uLightColor = gl.getUniformLocation(this.program, 'uLightColor');
    this.uTime = gl.getUniformLocation(this.program, 'uTime');

    gl.enableVertexAttribArray(this.aPos);
    gl.enableVertexAttribArray(this.aNormal);
    gl.enableVertexAttribArray(this.aUV);
    gl.enableVertexAttribArray(this.aFace);
  }

  initGeometry() {
    const gl = this.gl;
    // Generate coin geometry: cylinder with reeded edge
    const radius = 1.0;
    const height = 0.12;
    const segments = 128; // High for smooth reeds
    const reeds = 64; // Number of reeds around edge

    const positions = [];
    const normals = [];
    const uvs = [];
    const faces = [];
    const indices = [];

    // Face vertices (top and bottom)
    const faceVerts = 32; // radial segments for faces

    // Top face (front) - face = 1.0
    positions.push(0, height/2, 0); normals.push(0,1,0); uvs.push(0.5,0.5); faces.push(1.0);
    for(let i=0;i<=faceVerts;i++){
      const a = (i/faceVerts)*Math.PI*2;
      const r = radius * 0.95; // Inset slightly
      positions.push(Math.cos(a)*r, height/2, Math.sin(a)*r);
      normals.push(0,1,0);
      uvs.push(0.5+Math.cos(a)*0.475, 0.5+Math.sin(a)*0.475);
      faces.push(1.0);
    }
    const topCenter = 0;
    const topStart = 1;

    // Bottom face (back) - face = 0.0
    positions.push(0, -height/2, 0); normals.push(0,-1,0); uvs.push(0.5,0.5); faces.push(0.0);
    for(let i=0;i<=faceVerts;i++){
      const a = (i/faceVerts)*Math.PI*2;
      const r = radius * 0.95;
      positions.push(Math.cos(a)*r, -height/2, -Math.sin(a)*r); // Flip UV horizontally for back
      normals.push(0,-1,0);
      uvs.push(0.5+Math.cos(a)*0.475, 0.5-Math.sin(a)*0.475);
      faces.push(0.0);
    }
    const botCenter = 1 + faceVerts + 1;
    const botStart = botCenter + 1;

    // Top face triangles
    for(let i=0;i<faceVerts;i++){
      indices.push(topCenter, topStart+i+1, topStart+i);
    }

    // Bottom face triangles
    for(let i=0;i<faceVerts;i++){
      indices.push(botCenter, botStart+i, botStart+i+1);
    }

    // Reeded edge - face = 0.5
    // Each reed is a vertical ridge
    const edgeSegments = reeds * 4; // 4 verts per reed (two triangles)
    for(let r=0;r<reeds;r++){
      const a1 = (r/reeds)*Math.PI*2;
      const a2 = ((r+1)/reeds)*Math.PI*2;
      const aMid = (a1+a2)/2;

      // Reed peak
      const rPeak = radius;
      const rValley = radius * 0.92;

      // Four vertices per reed: top-peak, bot-peak, top-valley, bot-valley
      // Actually let's do proper triangles for each reed
      const vCount = positions.length/3;

      // Valley left
      positions.push(Math.cos(a1)*rValley, height/2, Math.sin(a1)*rValley);
      normals.push(Math.cos(a1), 0, Math.sin(a1));
      uvs.push(0.5, 0); faces.push(0.5);

      // Valley left bottom
      positions.push(Math.cos(a1)*rValley, -height/2, Math.sin(a1)*rValley);
      normals.push(Math.cos(a1), 0, Math.sin(a1));
      uvs.push(0.5, 1); faces.push(0.5);

      // Peak
      positions.push(Math.cos(aMid)*rPeak, height/2, Math.sin(aMid)*rPeak);
      normals.push(Math.cos(aMid), 0, Math.sin(aMid));
      uvs.push(1.0, 0); faces.push(0.5);

      // Peak bottom
      positions.push(Math.cos(aMid)*rPeak, -height/2, Math.sin(aMid)*rPeak);
      normals.push(Math.cos(aMid), 0, Math.sin(aMid));
      uvs.push(1.0, 1); faces.push(0.5);

      // Valley right
      positions.push(Math.cos(a2)*rValley, height/2, Math.sin(a2)*rValley);
      normals.push(Math.cos(a2), 0, Math.sin(a2));
      uvs.push(0.0, 0); faces.push(0.5);

      // Valley right bottom
      positions.push(Math.cos(a2)*rValley, -height/2, Math.sin(a2)*rValley);
      normals.push(Math.cos(a2), 0, Math.sin(a2));
      uvs.push(0.0, 1); faces.push(0.5);

      const base = vCount;
      // Two triangles per side of reed
      // Left side
      indices.push(base, base+1, base+2);
      indices.push(base+1, base+3, base+2);
      // Right side
      indices.push(base+2, base+3, base+4);
      indices.push(base+3, base+5, base+4);
    }

    this.indexCount = indices.length;

    // Buffers
    this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);

    this.posBuf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, this.posBuf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(positions), gl.STATIC_DRAW);
    gl.vertexAttribPointer(this.aPos, 3, gl.FLOAT, false, 0, 0);

    this.norBuf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, this.norBuf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(normals), gl.STATIC_DRAW);
    gl.vertexAttribPointer(this.aNormal, 3, gl.FLOAT, false, 0, 0);

    this.uvBuf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, this.uvBuf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(uvs), gl.STATIC_DRAW);
    gl.vertexAttribPointer(this.aUV, 2, gl.FLOAT, false, 0, 0);

    this.faceBuf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, this.faceBuf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(faces), gl.STATIC_DRAW);
    gl.vertexAttribPointer(this.aFace, 1, gl.FLOAT, false, 0, 0);

    this.idxBuf = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.idxBuf);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);

    gl.bindVertexArray(null);
  }

  initTextures() {
    const gl = this.gl;

    // Create procedural textures for hero (bronze-like)
    this.frontTex = this.createGLTexture(createCoinTexture('gold', 'front', 1024));
    this.backTex = this.createGLTexture(createCoinTexture('gold', 'back', 1024));
  }

  createGLTexture(canvas) {
    const gl = this.gl;
    const tex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, canvas);
    gl.generateMipmap(gl.TEXTURE_2D);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    return tex;
  }

  resize() {
    const dpr = Math.min(window.devicePixelRatio, 2);
    this.canvas.width = this.canvas.clientWidth * dpr;
    this.canvas.height = this.canvas.clientHeight * dpr;
    this.gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    this.aspect = this.canvas.width / this.canvas.height;
  }

  getMatrices() {
    const gl = this.gl;
    const fov = 45 * Math.PI/180;
    const near = 0.1, far = 100;

    // Projection
    const proj = new Float32Array(16);
    const f = 1.0/Math.tan(fov/2);
    proj[0] = f/this.aspect; proj[5] = f; proj[10] = (far+near)/(near-far); proj[11] = -1;
    proj[14] = 2*far*near/(near-far); proj[15] = 0;

    // View - camera at (0, 0.5, 3) looking at origin, slightly elevated
    const view = new Float32Array(16);
    const eye = [0, 0.35, 2.8];
    const target = [0, 0, 0];
    const up = [0, 1, 0];

    // LookAt
    const fwd = [target[0]-eye[0], target[1]-eye[1], target[2]-eye[2]];
    const flen = Math.hypot(...fwd);
    const fx = fwd[0]/flen, fy = fwd[1]/flen, fz = fwd[2]/flen;
    const sx = up[1]*fz - up[2]*fy;
    const sy = up[2]*fx - up[0]*fz;
    const sz = up[0]*fy - up[1]*fx;
    const slen = Math.hypot(sx,sy,sz);
    const snx = sx/slen, sny = sy/slen, snz = sz/slen;
    const ux = fy*snz - fz*sny;
    const uy = fz*snx - fx*snz;
    const uz = fx*sny - fy*snx;

    view[0]=snx; view[4]=sny; view[8]=snz; view[12]=-(snx*eye[0]+sny*eye[1]+snz*eye[2]);
    view[1]=ux;  view[5]=uy;  view[9]=uz;  view[13]=-(ux*eye[0]+uy*eye[1]+uz*eye[2]);
    view[2]=-fx; view[6]=-fy; view[10]=-fz; view[14]=-(-fx*eye[0]-fy*eye[1]-fz*eye[2]);
    view[3]=0; view[7]=0; view[11]=0; view[15]=1;

    return {proj, view, eye};
  }

  renderAtTime(t) {
    const gl = this.gl;
    this.time = t;

    const {proj, view, eye} = this.getMatrices();

    // Model matrix - animate rotation
    // t in [0,1] -> one full loop
    // Y rotation: 360 deg
    // X rotation: 180 deg (flip)
    const ry = t * Math.PI * 2;
    const rx = Math.sin(t * Math.PI * 2) * Math.PI * 0.5; // Smooth flip

    const model = new Float32Array(16);
    const cy = Math.cos(ry), sy = Math.sin(ry);
    const cx = Math.cos(rx), sx = Math.sin(rx);

    // Ry * Rx
    model[0] = cy; model[4] = sy*sx; model[8] = sy*cx; model[12] = 0;
    model[1] = 0;  model[5] = cx;    model[9] = -sx;   model[13] = 0;
    model[2] = -sy; model[6] = cy*sx; model[10] = cy*cx; model[14] = 0;
    model[3] = 0; model[7] = 0; model[11] = 0; model[15] = 1;

    gl.bindVertexArray(this.vao);
    gl.useProgram(this.program);

    gl.uniformMatrix4fv(this.uProj, false, proj);
    gl.uniformMatrix4fv(this.uView, false, view);
    gl.uniformMatrix4fv(this.uModel, false, model);
    gl.uniform3fv(this.uLightDir, new Float32Array([0.5, 1.0, 0.3]));
    gl.uniform3fv(this.uViewPos, new Float32Array(eye));
    gl.uniform1i(this.uFrontTex, 0);
    gl.uniform1i(this.uBackTex, 1);
    gl.uniform3fv(this.uBaseColor, new Float32Array([0.83, 0.69, 0.22])); // Gold
    gl.uniform1f(this.uRoughness, 0.15);
    gl.uniform1f(this.uMetalness, 1.0);
    gl.uniform3fv(this.uLightColor, new Float32Array([1.0, 0.95, 0.85]));
    gl.uniform1f(this.uTime, t * 10);

    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, this.frontTex);
    gl.activeTexture(gl.TEXTURE_1); gl.bindTexture(gl.TEXTURE_2D, this.backTex);

    gl.enable(gl.DEPTH_TEST);
    gl.enable(gl.CULL_FACE);
    gl.cullFace(gl.BACK);
    gl.clearColor(0.04, 0.04, 0.05, 1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

    gl.drawElements(gl.TRIANGLES, this.indexCount, gl.UNSIGNED_SHORT, 0);

    gl.bindVertexArray(null);
  }

  start() {
    if(this.animId) return;
    this.paused = false;
    const loop = () => {
      if(!this.paused){
        const t = (performance.now() / 1000 * 0.15) % 1; // 6-7 second loop
        this.renderAtTime(t);
      }
      this.animId = requestAnimationFrame(loop);
    };
    this.animId = requestAnimationFrame(loop);
  }

  pause() {
    this.paused = true;
    if(this.animId){
      cancelAnimationFrame(this.animId);
      this.animId = null;
    }
  }

  setTime(t) {
    t = Math.max(0, Math.min(1, t));
    this.renderAtTime(t);
  }
}

