// EDITION CANVAS RENDERER (2D Canvas - Static)
// ============================================
function renderEditionCanvas(canvas, metal, state) {
  const ctx = canvas.getContext('2d');
  const dpr = Math.min(window.devicePixelRatio, 2);
  const size = canvas.clientWidth;
  canvas.width = canvas.height = size * dpr;
  ctx.scale(dpr, dpr);

  const cx = size/2, cy = size/2;
  const r = size * 0.42;

  // Metal colors
  const metals = {
    bronze: { base:'#cd7f32', light:'#e8a85e', dark:'#8b5a2b', rim:'#ffd700' },
    silver: { base:'#b8bcc0', light:'#e8ebef', dark:'#8a8e92', rim:'#ffffff' },
    gold:   { base:'#d4af37', light:'#f0e68c', dark:'#9e7d2a', rim:'#fff8dc' },
    black:  { base:'#1a1a2e', light:'#2d2d44', dark:'#0a0a1a', rim:'#4a4a6a' }
  };
  const c = metals[metal] || metals.bronze;

  // Background subtle glow
  const bgGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, size*0.6);
  bgGrad.addColorStop(0, c.base + '20');
  bgGrad.addColorStop(1, 'transparent');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, size, size);

  // Coin body - outer rim (reeded)
  ctx.save();
  ctx.translate(cx, cy);

  // Reeded edge - draw as concentric rings with texture
  for(let i=0;i<3;i++){
    const rr = r + i*1.5;
    const grad = ctx.createRadialGradient(0,0,rr*0.8, 0,0, rr);
    grad.addColorStop(0, c.light);
    grad.addColorStop(0.5, c.base);
    grad.addColorStop(1, c.dark);
    ctx.beginPath(); ctx.arc(0,0,rr,0,Math.PI*2);
    ctx.fillStyle = grad; ctx.fill();
  }

  // Reed lines
  ctx.strokeStyle = c.dark;
  ctx.lineWidth = 1;
  for(let i=0;i<64;i++){
    const a = (i/64)*Math.PI*2;
    const r1 = r+1, r2 = r+4.5;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a)*r1, Math.sin(a)*r1);
    ctx.lineTo(Math.cos(a)*r2, Math.sin(a)*r2);
    ctx.stroke();
  }
  ctx.strokeStyle = c.light;
  for(let i=0;i<64;i++){
    const a = (i/64)*Math.PI*2 + Math.PI/64;
    const r1 = r+1, r2 = r+4.5;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a)*r1, Math.sin(a)*r1);
    ctx.lineTo(Math.cos(a)*r2, Math.sin(a)*r2);
    ctx.stroke();
  }

  // Main coin face
  const faceR = r;
  // Metallic gradient
  const faceGrad = ctx.createRadialGradient(-faceR*0.3, -faceR*0.3, 0, 0, 0, faceR);
  faceGrad.addColorStop(0, c.light);
  faceGrad.addColorStop(0.4, c.base);
  faceGrad.addColorStop(1, c.dark);
  ctx.beginPath(); ctx.arc(0,0,faceR,0,Math.PI*2);
  ctx.fillStyle = faceGrad; ctx.fill();

  // Specular highlight (static, as if light from top-left)
  const specGrad = ctx.createRadialGradient(-faceR*0.4, -faceR*0.4, 0, -faceR*0.4, -faceR*0.4, faceR*0.8);
  specGrad.addColorStop(0, 'rgba(255,255,255,0.4)');
  specGrad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.beginPath(); ctx.arc(0,0,faceR,0,Math.PI*2);
  ctx.fillStyle = specGrad; ctx.fill();

  // Brushed texture
  ctx.save();
  ctx.clip();
  for(let i=0;i<size*0.8;i++){
    ctx.strokeStyle = `rgba(255,255,255,${Math.random()*0.015})`;
    ctx.beginPath();
    ctx.moveTo(-size, Math.random()*size*2-size);
    ctx.lineTo(size, Math.random()*size*2-size);
    ctx.stroke();
  }
  ctx.restore();

  // Face content
  if(metal === 'black') {
    // Obsidian - minimal, mysterious
    ctx.font = `bold ${size*0.12}px system-ui`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = c.dark;
    ctx.fillText('Ω', 1, 1);
    ctx.fillStyle = c.rim;
    ctx.fillText('Ω', 0, 0);
  } else {
    // Emblem or denomination
    ctx.font = `bold ${size*0.08}px system-ui`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = c.dark;
    ctx.fillText(metal.toUpperCase(), 1, -size*0.02+1);
    ctx.fillStyle = c.light;
    ctx.fillText(metal.toUpperCase(), -1, -size*0.02-1);
    ctx.fillStyle = c.base;
    ctx.fillText(metal.toUpperCase(), 0, -size*0.02);

    ctx.font = `600 ${size*0.035}px system-ui`;
    ctx.fillStyle = c.dark;
    ctx.fillText('EDITION', 1, size*0.08+1);
    ctx.fillStyle = c.light;
    ctx.fillText('EDITION', -1, size*0.08-1);
    ctx.fillStyle = c.base;
    ctx.fillText('EDITION', 0, size*0.08);
  }

  // Inner rim
  ctx.strokeStyle = c.dark; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(0,0,faceR*0.95,0,Math.PI*2); ctx.stroke();
  ctx.strokeStyle = c.light; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(0,0,faceR*0.93,0,Math.PI*2); ctx.stroke();

  ctx.restore();

  // State overlay
  if(state === 'sold-out' || state === 'coming-soon'){
    ctx.fillStyle = 'rgba(10,10,12,0.6)';
    ctx.fillRect(0, 0, size, size);
    ctx.font = `700 ${size*0.07}px system-ui`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = state === 'sold-out' ? '#e04040' : '#8b8885';
    ctx.fillText(state === 'sold-out' ? 'SOLD OUT' : 'AUTUMN 2025', cx, cy);
  }
}

